css:
.cascade-sim-container {
    padding: 28px;
    background: #eef2f7;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}
.cascade-sim-header {
    background: linear-gradient(135deg, #0f1f3d 0%, #1a3566 100%);
    color: #ffffff;
    padding: 22px 30px;
    border-radius: 6px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 22px;
    border-left: 5px solid #00a3a1;
    flex-wrap: wrap;
    gap: 16px;
}
.cascade-sim-brand {
    display: flex;
    align-items: center;
    gap: 18px;
}
.cascade-sim-logo {
    background: #00a3a1;
    color: #ffffff;
    font-weight: 700;
    letter-spacing: 0.12em;
    padding: 12px 16px;
    border-radius: 4px;
    font-size: 0.95rem;
    box-shadow: 0 2px 6px rgba(0,163,161,0.35);
}
.cascade-sim-brand-text h1 {
    font-size: 1.5rem;
    margin: 0;
    color: #ffffff;
    letter-spacing: 0.02em;
    font-weight: 600;
}
.cascade-sim-subtitle {
    font-size: 0.82rem;
    color: #9bb3d1;
    margin-top: 4px;
    letter-spacing: 0.03em;
}
.cascade-sim-period-counter {
    background: rgba(0,163,161,0.15);
    color: #7fe0dd;
    padding: 10px 20px;
    border-radius: 4px;
    font-size: 0.8rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    border: 1px solid rgba(0,163,161,0.45);
    font-weight: 600;
}
.cascade-sim-period-counter span {
    font-weight: 700;
}
.cascade-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 22px;
}
.cascade-sim-status-card {
    background: #ffffff;
    border-radius: 6px;
    padding: 18px 20px;
    border-top: 3px solid #c5d2e3;
    box-shadow: 0 2px 4px rgba(15,31,61,0.06);
    position: relative;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.cascade-sim-status-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 14px rgba(15,31,61,0.1);
}
.cascade-sim-status-card-margin { border-top-color: #00a3a1; }
.cascade-sim-status-card-quality { border-top-color: #5b6dc8; }
.cascade-sim-status-card-access { border-top-color: #e8a93f; }
.cascade-sim-status-card-cash { border-top-color: #6cb67a; }
.cascade-sim-status-card-hero {
    background: linear-gradient(135deg, #0f1f3d, #1a3566);
    color: #ffffff;
    border-top: 3px solid #ff6b6b;
}
.cascade-sim-status-card-hero .cascade-sim-label { color: #9bb3d1; }
.cascade-sim-status-card-hero .cascade-sim-value { color: #ffffff; }
.cascade-sim-status-card-hero .cascade-sim-sublabel { color: #7fe0dd; }
.cascade-sim-label {
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #5a6b85;
    margin-bottom: 8px;
    font-weight: 700;
}
.cascade-sim-value {
    font-size: 1.95rem;
    font-weight: 700;
    color: #0f1f3d;
    line-height: 1.05;
    letter-spacing: -0.01em;
}
.cascade-sim-sublabel {
    font-size: 0.68rem;
    color: #8397b1;
    margin-top: 6px;
    letter-spacing: 0.02em;
}
.cascade-sim-briefing {
    background: #ffffff;
    border-radius: 6px;
    padding: 22px 26px;
    margin-bottom: 22px;
    border-left: 4px solid #00a3a1;
    box-shadow: 0 2px 4px rgba(15,31,61,0.06);
}
.cascade-sim-briefing-meta {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 10px;
    margin-bottom: 12px;
}
.cascade-sim-briefing-tag {
    display: inline-block;
    background: #00a3a1;
    color: #ffffff;
    padding: 4px 12px;
    border-radius: 3px;
    font-size: 0.68rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    font-weight: 700;
}
.cascade-sim-briefing-chips {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
}
.cascade-sim-chip {
    font-size: 0.7rem;
    font-weight: 600;
    letter-spacing: 0.04em;
    padding: 4px 10px;
    border-radius: 12px;
    border: 1px solid transparent;
}
.cascade-sim-chip-red { background: rgba(255,107,107,0.1); color: #c03b3b; border-color: rgba(255,107,107,0.35); }
.cascade-sim-chip-blue { background: rgba(91,109,200,0.1); color: #3d4da1; border-color: rgba(91,109,200,0.35); }
.cascade-sim-chip-amber { background: rgba(232,169,63,0.12); color: #a06a12; border-color: rgba(232,169,63,0.4); }
.cascade-sim-briefing h3 {
    font-size: 1.15rem;
    color: #0f1f3d;
    margin: 0 0 10px 0;
    font-weight: 600;
}
.cascade-sim-briefing #briefingText {
    color: #334661;
    font-size: 0.92rem;
    line-height: 1.58;
}
.cascade-sim-controls {
    background: #ffffff;
    border-radius: 6px;
    padding: 22px 26px;
    margin-bottom: 22px;
    box-shadow: 0 2px 4px rgba(15,31,61,0.06);
}
.cascade-sim-controls h3 {
    font-size: 0.85rem;
    color: #0f1f3d;
    margin: 0 0 18px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #e4eaf2;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-weight: 700;
}
.cascade-sim-decision-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 18px;
    margin-bottom: 20px;
}
.cascade-sim-decision-field label {
    display: block;
    font-size: 0.8rem;
    color: #334661;
    margin-bottom: 6px;
    font-weight: 600;
    letter-spacing: 0.02em;
}
.cascade-sim-decision-hint {
    font-size: 0.72rem;
    color: #8397b1;
    margin-top: 6px;
    min-height: 14px;
    line-height: 1.4;
}
.cascade-sim-controls select,
.cascade-sim-controls input[type="number"],
.cascade-sim-controls input[type="text"] {
    background: #ffffff;
    border: 1px solid #c5d2e3;
    color: #0f1f3d;
    border-radius: 4px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.9rem;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
    font-family: inherit;
}
.cascade-sim-controls select:focus,
.cascade-sim-controls input:focus {
    outline: none;
    border-color: #00a3a1;
    box-shadow: 0 0 0 3px rgba(0,163,161,0.15);
}
.cascade-sim-controls select option {
    background: #ffffff;
    color: #0f1f3d;
    padding: 8px;
}
.cascade-sim-actions {
    display: flex;
    gap: 12px;
    align-items: center;
    flex-wrap: wrap;
    border-top: 1px solid #e4eaf2;
    margin-top: 4px;
    padding-top: 16px;
}
.cascade-sim-container .btn-primary {
    background: #0f1f3d;
    border: 1px solid #0f1f3d;
    color: #ffffff;
    padding: 10px 26px;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    border-radius: 4px;
    font-size: 0.82rem;
    transition: background 0.2s ease, transform 0.1s ease;
}
.cascade-sim-container .btn-primary:hover {
    background: #00a3a1;
    border-color: #00a3a1;
    color: #ffffff;
}
.cascade-sim-container .btn-primary:active {
    transform: translateY(1px);
}
.cascade-sim-container .btn-outline-secondary {
    border-color: #c5d2e3;
    color: #5a6b85;
    border-radius: 4px;
    background: #ffffff;
    font-size: 0.78rem;
}
.cascade-sim-container .btn-outline-secondary:hover {
    background: #f4f6fa;
    color: #0f1f3d;
    border-color: #9bb3d1;
}
.cascade-sim-chart-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(360px, 1fr));
    gap: 16px;
    margin-bottom: 22px;
}
.cascade-sim-chart-card {
    background: #ffffff;
    border-radius: 6px;
    padding: 20px 22px;
    box-shadow: 0 2px 4px rgba(15,31,61,0.06);
    display: flex;
    flex-direction: column;
}
.cascade-sim-chart-card h4 {
    font-size: 0.78rem;
    color: #334661;
    margin: 0 0 14px 0;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-weight: 700;
}
.cascade-sim-chart-canvas-wrap {
    position: relative;
    height: 260px;
}
.cascade-sim-history {
    background: #ffffff;
    border-radius: 6px;
    padding: 20px 24px;
    box-shadow: 0 2px 4px rgba(15,31,61,0.06);
}
.cascade-sim-history h4 {
    font-size: 0.78rem;
    color: #334661;
    margin: 0 0 14px 0;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-weight: 700;
}
.cascade-sim-history table {
    margin: 0;
    font-size: 0.85rem;
    width: 100%;
}
.cascade-sim-history table thead th {
    background: #0f1f3d;
    color: #ffffff;
    border: none;
    font-size: 0.7rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    padding: 10px 14px;
    font-weight: 600;
}
.cascade-sim-history table tbody td {
    padding: 10px 14px;
    border-top: 1px solid #e4eaf2;
    color: #334661;
    background: #ffffff;
}
.cascade-sim-history table tbody tr:nth-child(even) td {
    background: #f8fafc;
}
.cascade-sim-history table tbody tr:hover td {
    background: #eef6f6;
    color: #0f1f3d;
}
.cascade-sim-lock-note {
    background: #fff6e5;
    border: 1px solid #e8c98a;
    border-left: 4px solid #e8a93f;
    color: #7a5510;
    border-radius: 4px;
    padding: 10px 14px;
    font-size: 0.82rem;
    line-height: 1.5;
    margin-bottom: 14px;
}
.cascade-sim-outcome {
    background: #ffffff;
    border: 1px solid #e4eaf2;
    border-left: 4px solid #1a3566;
    border-radius: 6px;
    padding: 18px 20px;
    margin-bottom: 22px;
    box-shadow: 0 1px 3px rgba(15,31,61,0.05);
}
.cascade-sim-outcome-head {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 12px;
    flex-wrap: wrap;
    margin-bottom: 12px;
    padding-bottom: 10px;
    border-bottom: 1px solid #eef2f7;
}
.cascade-sim-outcome-head h4 {
    margin: 0;
    font-size: 0.95rem;
    font-weight: 700;
    color: #0f1f3d;
    letter-spacing: 0.01em;
}
.cascade-sim-outcome-round {
    font-size: 0.68rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #5a6b85;
    background: #f2f6fb;
    border-radius: 3px;
    padding: 4px 8px;
}
.cascade-sim-outcome-body > div + div {
    margin-top: 14px;
}
.cascade-sim-outcome-label {
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #8397b1;
    margin-bottom: 6px;
}
.cascade-sim-outcome-list {
    margin: 0;
    padding-left: 18px;
    font-size: 0.85rem;
    line-height: 1.55;
    color: #334661;
}
.cascade-sim-outcome-list li {
    margin-bottom: 4px;
}
.cascade-sim-outcome-notes li {
    color: #7a2f2f;
}
.cascade-sim-outcome-clean {
    margin: 0;
    font-size: 0.85rem;
    color: #3d7a4d;
}
.cascade-sim-outcome-next {
    margin: 10px 0 0;
    font-size: 0.78rem;
    color: #5a6b85;
    font-style: italic;
}
.cascade-sim-outcome-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}
.cascade-sim-outcome-chip {
    font-size: 0.72rem;
    font-weight: 600;
    border-radius: 3px;
    padding: 5px 9px;
    border: 1px solid #dfe6f0;
    background: #f7f9fc;
    color: #334661;
    white-space: nowrap;
}
.cascade-sim-outcome-chip em {
    font-style: normal;
    font-weight: 700;
    margin-left: 4px;
}
.cascade-sim-outcome-up {
    background: rgba(108,182,122,0.12);
    border-color: rgba(108,182,122,0.4);
    color: #2f6b40;
}
.cascade-sim-outcome-down {
    background: rgba(255,107,107,0.1);
    border-color: rgba(255,107,107,0.35);
    color: #a83232;
}
.cascade-sim-outcome-flat {
    color: #6b7c96;
}
.cascade-sim-complete {
    text-align: left;
    color: #0f1f3d;
    font-size: 0.9rem;
    line-height: 1.55;
}
.cascade-sim-complete-head h3 {
    margin: 0 0 4px;
    font-size: 1.1rem;
    font-weight: 700;
}
.cascade-sim-complete-sub {
    margin: 0 0 16px;
    font-size: 0.8rem;
    color: #5a6b85;
}
.cascade-sim-complete-hero {
    display: flex;
    gap: 14px;
    flex-wrap: wrap;
    margin-bottom: 18px;
}
.cascade-sim-complete-score,
.cascade-sim-complete-rating {
    flex: 1 1 160px;
    background: #0f1f3d;
    color: #ffffff;
    border-radius: 6px;
    padding: 14px 16px;
}
.cascade-sim-complete-score-num {
    font-size: 2rem;
    font-weight: 700;
    line-height: 1;
}
.cascade-sim-complete-score-den {
    font-size: 0.85rem;
    color: #9bb3d1;
    margin-left: 4px;
}
.cascade-sim-complete-score-label {
    font-size: 0.66rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #9bb3d1;
    margin-top: 8px;
}
.cascade-sim-complete-rating-value {
    font-size: 1.3rem;
    font-weight: 700;
    line-height: 1.2;
}
.cascade-sim-rating-elite,
.cascade-sim-rating-strong { color: #7fe0dd; }
.cascade-sim-rating-above { color: #b9e6a6; }
.cascade-sim-rating-below { color: #f4cf8a; }
.cascade-sim-rating-distressed,
.cascade-sim-rating-none { color: #ff9b9b; }
.cascade-sim-complete-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 18px;
    font-size: 0.85rem;
}
.cascade-sim-complete-table th,
.cascade-sim-complete-table td {
    text-align: left;
    padding: 7px 10px;
    border-bottom: 1px solid #eef2f7;
}
.cascade-sim-complete-table th {
    font-weight: 600;
    color: #334661;
    width: 42%;
}
.cascade-sim-complete-bench {
    color: #8397b1;
    font-size: 0.75rem;
    text-align: right;
}
.cascade-sim-complete h4 {
    font-size: 0.8rem;
    font-weight: 700;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #5a6b85;
    margin: 18px 0 8px;
}
.cascade-sim-complete-list {
    margin: 0;
    padding-left: 18px;
}
.cascade-sim-complete-list li {
    margin-bottom: 6px;
}
.cascade-sim-complete-ledger li {
    color: #334661;
}
.cascade-sim-complete-round {
    display: inline-block;
    font-size: 0.66rem;
    font-weight: 700;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #5a6b85;
    background: #f2f6fb;
    border-radius: 3px;
    padding: 2px 6px;
    margin-right: 6px;
}
.cascade-sim-complete-clean {
    margin: 0;
    color: #3d7a4d;
}
.cascade-sim-complete-foot {
    margin: 18px 0 0;
    font-size: 0.78rem;
    color: #8397b1;
}
@media (max-width: 768px) {
    .cascade-sim-container { padding: 16px; }
    .cascade-sim-header {
        flex-direction: column;
        gap: 14px;
        align-items: flex-start;
        padding: 18px;
    }
    .cascade-sim-status-cards { grid-template-columns: repeat(2, 1fr); }
    .cascade-sim-chart-grid { grid-template-columns: 1fr; }
    .cascade-sim-value { font-size: 1.5rem; }
    .cascade-sim-brand-text h1 { font-size: 1.15rem; }
    .cascade-sim-outcome { padding: 14px 15px; }
    .cascade-sim-outcome-chips { gap: 6px; }
    .cascade-sim-complete-hero { flex-direction: column; }
    .cascade-sim-complete-bench { text-align: left; }
}

