        getPerformanceSummary(history) {
            var rows = Array.isArray(history) ? history : [];
            if (!rows.length) {
                return {
                    totalPeriods: 0,
                    performanceScore: 0,
                    operatingMargin: 0,
                    qualityComposite: 0,
                    accessScore: 0,
                    vbcPerformance: 0,
                    workforceHealth: 0,
                    daysCashOnHand: 0,
                    regulatoryFlags: 0,
                    performanceKey: 'none',
                    performance: this._t('rating_none'),
                    insights: [this._t('report_no_history')],
                    complianceNotes: []
                };
            }

            var last = rows[rows.length - 1];
            var r = last.results || {};
            var score = r.performanceScore || 0;
            var margin = r.operatingMargin || 0;
            var quality = r.qualityComposite || 0;
            var access = r.accessScore || 0;
            var flags = r.regulatoryFlags || 0;

            var key = 'distressed';
            if (score >= 55) key = 'below';
            if (score >= 65) key = 'above';
            if (score >= 75) key = 'strong';
            if (score >= 82) key = 'elite';

            var insights = [];
            if (margin < 1.5) insights.push(this._t('insight_margin_weak'));
            else if (margin >= 3.5) insights.push(this._t('insight_margin_strong'));
            if (flags >= 3) insights.push(this._t('insight_flags'));
            if (access < 60) insights.push(this._t('insight_access'));
            if (quality >= 80) insights.push(this._t('insight_quality'));
            if (!insights.length) insights.push(this._t('insight_balanced'));

            var ledger = [];
            rows.forEach(function(row, i) {
                var notes = (row.results && row.results.regulatoryNotes) || [];
                notes.forEach(function(n) { ledger.push({ round: i + 1, note: n }); });
            });

            return {
                totalPeriods: rows.length,
                performanceScore: Math.round(score),
                operatingMargin: margin,
                qualityComposite: quality,
                accessScore: access,
                vbcPerformance: r.vbcPerformance || 0,
                workforceHealth: r.workforceHealth || 0,
                daysCashOnHand: r.daysCashOnHand || 0,
                regulatoryFlags: flags,
                performanceKey: key,
                performance: this._t('rating_' + key),
                insights: insights,
                complianceNotes: ledger
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var n = parseInt(s.totalPeriods, 10) || 0;
            if (!n) {
                return '<div class="cascade-sim-complete"><p>' + this._esc(this._t('report_no_history')) + '</p></div>';
            }

            var self = this;
            var rows = [
                ['report_margin', this._num(s.operatingMargin, 2) + '%', this._t('report_margin_bench')],
                ['report_quality', Math.round(s.qualityComposite || 0) + ' / 100', this._t('quality_sub')],
                ['report_access', Math.round(s.accessScore || 0) + ' / 100', this._t('access_sub')],
                ['report_vbc', Math.round(s.vbcPerformance || 0) + ' / 100', ''],
                ['report_workforce', Math.round(s.workforceHealth || 0) + ' / 100', ''],
                ['report_cash', Math.round(s.daysCashOnHand || 0) + ' ' + this._t('unit_days'), this._t('report_cash_bench')],
                ['report_flags', String(Math.round(s.regulatoryFlags || 0)), '']
            ];

            var html = '<div class="cascade-sim-complete">';
            html += '<div class="cascade-sim-complete-head">';
            html += '<h3>' + this._esc(this._t('report_title')) + '</h3>';
            html += '<p class="cascade-sim-complete-sub">' + this._esc(this._t('report_subtitle', { n: n })) + '</p>';
            html += '</div>';

            html += '<div class="cascade-sim-complete-hero">';
            html += '<div class="cascade-sim-complete-score"><span class="cascade-sim-complete-score-num">'
                 + Math.round(s.performanceScore || 0) + '</span><span class="cascade-sim-complete-score-den">/ 100</span>'
                 + '<div class="cascade-sim-complete-score-label">' + this._esc(this._t('report_score')) + '</div></div>';
            html += '<div class="cascade-sim-complete-rating"><div class="cascade-sim-complete-rating-value cascade-sim-rating-'
                 + this._esc(s.performanceKey || 'distressed') + '">' + this._esc(s.performance || '') + '</div>'
                 + '<div class="cascade-sim-complete-score-label">' + this._esc(this._t('report_rating')) + '</div></div>';
            html += '</div>';

            html += '<table class="cascade-sim-complete-table"><tbody>';
            rows.forEach(function(row) {
                html += '<tr><th>' + self._esc(self._t(row[0])) + '</th><td>' + self._esc(row[1]) + '</td>'
                     + '<td class="cascade-sim-complete-bench">' + self._esc(row[2]) + '</td></tr>';
            });
            html += '</tbody></table>';

            html += '<h4>' + this._esc(this._t('report_insights')) + '</h4><ul class="cascade-sim-complete-list">';
            (s.insights || []).forEach(function(i) { html += '<li>' + self._esc(i) + '</li>'; });
            html += '</ul>';

            html += '<h4>' + this._esc(this._t('report_compliance')) + '</h4>';
            var ledger = s.complianceNotes || [];
            if (!ledger.length) {
                html += '<p class="cascade-sim-complete-clean">' + this._esc(this._t('report_compliance_clean')) + '</p>';
            } else {
                html += '<ul class="cascade-sim-complete-list cascade-sim-complete-ledger">';
                ledger.forEach(function(entry) {
                    html += '<li><span class="cascade-sim-complete-round">'
                         + self._esc(self._t('period_label')) + ' ' + entry.round + '</span> '
                         + self._esc(entry.note) + '</li>';
                });
                html += '</ul>';
            }

            html += '<p class="cascade-sim-complete-foot">' + this._esc(this._t('report_footer', { n: n })) + '</p>';
            html += '</div>';
            return html;
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.operatingMargin < 1.0) return this._t('hint_margin');
            if (results.regulatoryFlags > 3) return this._t('hint_reg');
            if (results.accessScore < 55) return this._t('hint_access');
            if (results.vbcPerformance < 40) return this._t('hint_vbc');
            if (results.workforceHealth < 45) return this._t('hint_workforce');
            return null;
        }

