        _render(state, opts) {
            opts = opts || {};
            var idx = this._roundIndex(state);
            var round = this.ROUNDS[idx];
            if (!round) return;
            var rn = 'r' + (idx + 1);

            this._setHtml('roundTag', this._esc(this._t(rn + '_tag')));
            this._setHtml('briefingTitle', this._esc(this._t(rn + '_title')));
            this._setHtml('briefingText', this._esc(this._t(rn + '_brief')));
            this._setAria('marginChart', this._t('chart_margin_aria'));
            this._setAria('compositeChart', this._t('chart_composite_aria'));

            var placeholder = this._t('select_placeholder');
            var sim = window.mySimulation;

            for (var i = 0; i < round.decisions.length; i++) {
                var dec = round.decisions[i];
                var dn = rn + '_' + dec.key;

                this._setHtml(dec.key + 'Label', this._esc(this._t(dn + '_label')));
                this._setHtml(dec.key + 'Hint', this._esc(this._t(dn + '_hint')));

                var selectEl = document.getElementById(dec.key + 'Input');
                if (!selectEl) continue;

                var keep = opts.blank ? '' : String(selectEl.value || '');
                selectEl.innerHTML = '';

                var ph = document.createElement('option');
                ph.value = '';
                ph.textContent = placeholder;
                ph.disabled = true;
                ph.selected = true;
                selectEl.appendChild(ph);

                for (var k = 0; k < dec.options.length; k++) {
                    var o = document.createElement('option');
                    o.value = dec.options[k].value;
                    o.textContent = this._t('opt_' + dec.options[k].value);
                    selectEl.appendChild(o);
                }

                var restore = this._findOption(dec, keep) ? keep : '';
                selectEl.value = restore;
                if (sim && sim.state && sim.state.decisions) sim.state.decisions[dec.key] = restore;
            }
        }

        _renderOutcome(state, results, isFinal) {
            var panel = document.getElementById('outcomePanel');
            if (!panel) return;

            var res = results;
            if (!res) {
                var hist = Array.isArray(state.history) ? state.history : [];
                res = hist.length ? hist[hist.length - 1].results : null;
            }
            if (!res) {
                panel.style.display = 'none';
                this._setHtml('outcomeRound', '');
                this._setHtml('outcomeText', '');
                this._setHtml('outcomeDeltas', '');
                this._setHtml('outcomeFlags', '');
                return;
            }

            panel.style.display = '';
            this._setHtml('outcomeRound', this._esc(res.round || ''));

            var chosen = (res.picks || []).map(function(p) { return p.value; });
            var self = this;
            var list = chosen.length
                ? chosen.map(function(v) { return '<li>' + self._esc(self._t('opt_' + v)) + '</li>'; }).join('')
                : '<li>' + this._esc(res.summary || '') + '</li>';
            this._setHtml('outcomeText',
                '<div class="cascade-sim-outcome-label">' + this._esc(this._t('outcome_decided')) + '</div>'
                + '<ul class="cascade-sim-outcome-list">' + list + '</ul>');

            var prev = this._previousResults(state, res);
            var metrics = [
                ['report_margin', res.operatingMargin, prev ? prev.operatingMargin : 2.8, 2, '%'],
                ['report_quality', res.qualityComposite, prev ? prev.qualityComposite : 62, 0, ''],
                ['report_access', res.accessScore, prev ? prev.accessScore : 75, 0, ''],
                ['report_vbc', res.vbcPerformance, prev ? prev.vbcPerformance : 45, 0, ''],
                ['report_workforce', res.workforceHealth, prev ? prev.workforceHealth : 55, 0, ''],
                ['report_cash', res.daysCashOnHand, prev ? prev.daysCashOnHand : 138, 0, ''],
                ['report_flags', res.regulatoryFlags, prev ? prev.regulatoryFlags : 2, 0, ''],
                ['report_score', res.performanceScore, prev ? prev.performanceScore : 64, 0, '']
            ];
            var chips = metrics.map(function(m) {
                var now = Number(m[1]) || 0, before = Number(m[2]) || 0;
                var d = now - before;
                var good = (m[0] === 'report_flags') ? (d < 0) : (d > 0);
                var cls = Math.abs(d) < 0.005 ? 'flat' : (good ? 'up' : 'down');
                var sign = d > 0 ? '+' : (d < 0 ? '−' : '±');
                return '<span class="cascade-sim-outcome-chip cascade-sim-outcome-' + cls + '">'
                    + self._esc(self._t(m[0])) + ' ' + self._esc(self._num(now, m[3]) + m[4])
                    + ' <em>' + sign + self._esc(self._num(Math.abs(d), m[3])) + m[4] + '</em></span>';
            }).join('');
            this._setHtml('outcomeDeltas',
                '<div class="cascade-sim-outcome-label">' + this._esc(this._t('outcome_moved')) + '</div>'
                + '<div class="cascade-sim-outcome-chips">' + chips + '</div>');

            var notes = res.regulatoryNotes || [];
            var flagsHtml = '<div class="cascade-sim-outcome-label">' + this._esc(this._t('outcome_compliance')) + '</div>';
            if (!notes.length) {
                flagsHtml += '<p class="cascade-sim-outcome-clean">' + this._esc(this._t('outcome_clean')) + '</p>';
            } else {
                flagsHtml += '<ul class="cascade-sim-outcome-list cascade-sim-outcome-notes">'
                    + notes.map(function(nt) { return '<li>' + self._esc(nt) + '</li>'; }).join('')
                    + '</ul>';
            }
            var nextIdx = this._roundIndex(state);
            if (isFinal || this._isComplete(state)) {
                flagsHtml += '<p class="cascade-sim-outcome-next">' + this._esc(this._t('outcome_final')) + '</p>';
            } else {
                flagsHtml += '<p class="cascade-sim-outcome-next">'
                    + this._esc(this._t('outcome_next', { round: this._t('r' + (nextIdx + 1) + '_tag') })) + '</p>';
            }
            this._setHtml('outcomeFlags', flagsHtml);
        }

        _lockForCompletion(state, alreadyShown) {
            this._render(state, { blank: false });
            var sim = window.mySimulation;
            try { if (sim && sim.uiManager && sim.uiManager.disableInputs) sim.uiManager.disableInputs(); } catch (e) {}
            var note = document.getElementById('lockNote');
            if (note) {
                note.style.display = '';
                note.innerHTML = this._esc(this._t('decisions_locked'));
            }
            this._renderOutcome(state, null, true);
            if (!alreadyShown) {
                try { if (sim && typeof sim.showCompletion === 'function') sim.showCompletion(); } catch (e) {}
            }
        }

        _unlock() {
            var ids = ['d1Input', 'd2Input', 'd3Input', 'nextPeriodBtn', 'undoBtn'];
            for (var i = 0; i < ids.length; i++) {
                var el = document.getElementById(ids[i]);
                if (!el) continue;
                el.disabled = false;
                if (el.style) { el.style.opacity = ''; el.style.cursor = ''; }
                if (typeof el.removeAttribute === 'function') el.removeAttribute('data-usf-disabled');
            }
            var note = document.getElementById('lockNote');
            if (note) { note.style.display = 'none'; note.innerHTML = ''; }
        }

        // ==========================================================
        // HELPERS
        // ==========================================================

        _computeComposite(ds) {
            var marginScore = Math.max(0, Math.min(100, 30 + ds.operatingMargin * 14.5));
            var regScore = Math.max(0, Math.min(100, 100 - 15 * ds.regulatoryFlags));
            var composite =
                0.25 * marginScore +
                0.20 * ds.qualityComposite +
                0.15 * ds.accessScore +
                0.15 * ds.vbcPerformance +
                0.10 * ds.workforceHealth +
                0.10 * regScore +
                0.05 * ds.strategicOptionality;
            return Math.round(composite);
        }

        _syncDecisionsFromDom(decisions) {
            var keys = ['d1', 'd2', 'd3'];
            for (var i = 0; i < keys.length; i++) {
                var el = document.getElementById(keys[i] + 'Input');
                if (el) decisions[keys[i]] = el.value;
            }
        }

        _findOption(dec, value) {
            if (value === null || value === undefined || value === '') return null;
            for (var i = 0; i < dec.options.length; i++) {
                if (dec.options[i].value === value) return dec.options[i];
            }
            return null;
        }

        _panelMatchesRound(round) {
            for (var i = 0; i < round.decisions.length; i++) {
                var el = document.getElementById(round.decisions[i].key + 'Input');
                if (!el || !el.options) return false;
                var have = [];
                for (var k = 0; k < el.options.length; k++) {
                    if (el.options[k].value) have.push(String(el.options[k].value));
                }
                var want = round.decisions[i].options.map(function(o) { return o.value; });
                if (have.length !== want.length) return false;
                for (var j = 0; j < want.length; j++) if (have.indexOf(want[j]) === -1) return false;
            }
            return true;
        }

        _maxPeriods(state) { return parseInt(state && state.maxPeriods, 10) || this.ROUNDS.length; }

        _isComplete(state) {
            if (!state) return false;
            var max = this._maxPeriods(state);
            var hist = Array.isArray(state.history) ? state.history.length : 0;
            return hist >= max || (parseInt(state.currentPeriod, 10) || 1) > max;
        }

        _roundIndex(state) {
            var p = parseInt(state && state.currentPeriod, 10);
            if (!p || p < 1) p = 1;
            return Math.min(Math.max(p - 1, 0), this.ROUNDS.length - 1);
        }

        _previousResults(state, current) {
            var hist = Array.isArray(state.history) ? state.history : [];
            for (var i = hist.length - 1; i >= 0; i--) {
                var r = hist[i].results;
                if (r && r !== current && !(current && r.period === current.period)) return r;
            }
            return null;
        }

        _notify(msg, kind) {
            try {
                var sim = window.mySimulation;
                if (sim && sim.uiManager && typeof sim.uiManager.showNotification === 'function') {
                    sim.uiManager.showNotification(msg, kind || 'info');
                }
            } catch (e) { /* silent */ }
        }

        _setHtml(id, html) {
            var el = document.getElementById(id);
            if (el) el.innerHTML = html;
        }

        _setAria(id, value) {
            var el = document.getElementById(id);
            if (el && typeof el.setAttribute === 'function') el.setAttribute('aria-label', value);
        }

        _esc(v) {
            return String(v === null || v === undefined ? '' : v)
                .split('&').join('&amp;')
                .split('<').join('&lt;')
                .split('>').join('&gt;')
                .split('"').join('&quot;');
        }

        _num(v, dp) {
            var n = Number(v);
            if (!isFinite(n)) return '0';
            return dp ? n.toFixed(dp) : String(Math.round(n));
        }

        /* window.mySimulation.t() delegates to vcI18n and does NOT interpolate,
         * so {placeholder} substitution and the en fallback are done here. */
        _t(key, vars) {
            var s = null;
            try {
                var sim = window.mySimulation;
                if (sim && typeof sim.t === 'function') {
                    var v = sim.t(key);
                    if (typeof v === 'string' && v && v !== key) s = v;
                }
            } catch (e) { /* silent */ }
            if (s === null) {
                if (!this._trCache) { try { this._trCache = this.getTranslations(); } catch (e) { this._trCache = { en: {} }; } }
                var en = (this._trCache && this._trCache.en) || {};
                s = Object.prototype.hasOwnProperty.call(en, key) ? en[key] : key;
            }
            if (vars) {
                Object.keys(vars).forEach(function(k) { s = s.split('{' + k + '}').join(String(vars[k])); });
            }
            return s;
        }

